sql:
SELECT PNO
  FROM PRODUCT
 WHERE PRICE BETWEEN 1500 AND 3000;

SELECT CNO
  FROM CUST
 WHERE CNAME LIKE '_A%';

SELECT ENO
  FROM EMP
 WHERE MGR NOT IN (1, NULL);

SELECT ENO
  FROM SALES
 WHERE NOT (COMM > 100);

SELECT ENO
  FROM EMP
 WHERE DEPT IN (10, 30, 50);

SELECT CNO
  FROM CUST
 WHERE NAME LIKE 'A%';

SELECT MNO
  FROM MEMBER
 WHERE NAME BETWEEN 'B' AND 'D';

SELECT ENO
  FROM EMP
 WHERE NOT DEPT = 10 AND SAL > 200;

SELECT ENO
  FROM EMP
 WHERE COMM IS NOT NULL OR SAL >= 300;

SELECT (SELECT COUNT(*) FROM SALES WHERE NOT (COMM <= 100))             AS A,
       (SELECT COUNT(*) FROM SALES WHERE COMM > 100 OR COMM IS NULL) AS B
  FROM DUAL;

SELECT ID
  FROM CODES
 WHERE CODE LIKE '__';

SELECT ID
  FROM ITEMS
 WHERE NAME LIKE '%\%%' ESCAPE '\';

SELECT ENO
  FROM EMP
 WHERE SAL + COMM >= 300;

SELECT ENO
  FROM EMP
 WHERE JOB = 'clerk';

SELECT MNO
  FROM MEMBER
 WHERE NAME NOT LIKE 'K%';
